#!/usr/bin/env bash\nset -euo pipefail\n\nTARGET="${1:-/}"\nTHRESHOLD=80\n\n# Get usage percentage of the filesystem containing TARGET\nUSAGE=$(df -P "$TARGET" | awk 'NR==2 {print $5}' | tr -d '%')\n\nif [[ -z "$USAGE" ]]; then\n  echo "Error: Unable to determine disk usage."\n  exit 2\nfi\n\nif (( USAGE > THRESHOLD )); then\n  cat <<'EOF'\n   _____\n  /     \\n | () () |\n  \\  ^  /\n   |||||\n   |||||\nEOF\n  printf "   Disk space critical! (%s%% used)\n" "$USAGE"\n  exit 1\nelse\n  cat <<'EOF'\n   \\   /  \n    .-.   \n ‒ (   ) ‒\n    `-’   \n   /   \\  \nEOF\n  printf "   All clear! (%s%% used)\n" "$USAGE"\n  exit 0\nfi\n
